1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"math"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	const factsProposalsFileName = "proposals.ndjson"
16	
17	func factsProposalsRelPath(branch string) string {
18		return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsProposalsFileName))
19	}
20	
21	// loadFactProposals reads a branch's pending proposals; a missing file yields
22	// none. A malformed line is a hard error so a corrupt queue is surfaced.
23	func loadFactProposals(brainDir, branch string) ([]factProposal, error) {
24		data, present, err := readMemoryStateFile(brainDir, factsProposalsRelPath(branch), "fact proposals", defaultMaxReadBytes)
25		if err != nil {
26			return nil, err
27		}
28		if !present {
29			return nil, nil
30		}
31		var proposals []factProposal
32		for i, line := range strings.Split(string(data), "\n") {
33			line = strings.TrimSpace(line)
34			if line == "" {
35				continue
36			}
37			var p factProposal
38			if err := json.Unmarshal([]byte(line), &p); err != nil {
39				return nil, fmt.Errorf("parse %s line %d: %w", factsProposalsRelPath(branch), i+1, err)
40			}
41			proposals = append(proposals, p)
42		}
43		return proposals, nil
44	}
45	
46	// writeFactProposals persists a branch's pending proposals, deduplicated by
47	// (action, candidate, target) and sorted for a stable file. An empty set
48	// removes the file so a fully-resolved branch leaves no stale queue.
49	func writeFactProposals(brainDir, branch string, proposals []factProposal) error {
50		deduped := dedupeProposals(proposals)
51		if len(deduped) == 0 {
52			return removeBrainRelativeFile(brainDir, factsProposalsRelPath(branch))
53		}
54		var buf strings.Builder
55		for _, p := range deduped {
56			data, err := json.Marshal(p)
57			if err != nil {
58				return err
59			}
60			buf.Write(data)
61			buf.WriteByte('\n')
62		}
63		return writeBrainRelativeFileAtomic(brainDir, factsProposalsRelPath(branch), []byte(buf.String()), 0o600)
64	}
65	
66	// dedupeProposals collapses identical queue entries. Its identity must match
67	// factsync.ProposalID — action, candidate, target, BRANCH and PROPOSED_BY —
68	// because that is the id the shared review queue, the shared-proposal ledger and
69	// the `facts review` interlock all key on. Keying on the triple alone silently
70	// merges rows those layers treat as distinct: distill's private, unattributed
71	// backlog entry and a cross-member conflict `facts sync` raised for the same two
72	// facts collapse onto whichever landed first, and since the private one is
73	// written first the member-attributed entry is the one that disappears — so the
74	// conflict is never published to the team and the member settles locally a
75	// decision the next sync will overrule.
76	func dedupeProposals(proposals []factProposal) []factProposal {
77		seen := make(map[string]struct{}, len(proposals))
78		out := make([]factProposal, 0, len(proposals))
79		key := func(p factProposal) string {
80			return strings.Join([]string{p.Action, p.CandidateID, p.TargetID, p.Branch, p.ProposedBy}, "\x00")
81		}
82		for _, p := range proposals {
83			k := key(p)
84			if _, ok := seen[k]; ok {
85				continue
86			}
87			seen[k] = struct{}{}
88			out = append(out, p)
89		}
90		sort.SliceStable(out, func(i, j int) bool {
91			if out[i].TargetID != out[j].TargetID {
92				return out[i].TargetID < out[j].TargetID
93			}
94			if out[i].CandidateID != out[j].CandidateID {
95				return out[i].CandidateID < out[j].CandidateID
96			}
97			if out[i].Action != out[j].Action {
98				return out[i].Action < out[j].Action
99			}
100			if out[i].Branch != out[j].Branch {
101				return out[i].Branch < out[j].Branch
102			}
103			return out[i].ProposedBy < out[j].ProposedBy
104		})
105		return out
106	}
107	
108	const (
109		// maxReconcileExisting bounds how many existing active facts at a
110		// candidate's paths are shown to the agent, keeping the reconcile prompt
111		// bounded even on busy paths. When more exist, the most recently updated
112		// are shown and the cap is reported as a warning (no silent truncation).
113		maxReconcileExisting = 50
114	)
115	
116	// reconcilePrompt is the static system prompt for the reconcile pass. The
117	// dynamic candidate/existing lists are supplied on stdin (see reconcileInput).
118	// Like the distill prompt it must not begin with a dash — the agent runners
119	// pass it as a positional CLI argument.
120	func reconcilePrompt() string {
121		return `You are deduplicating durable repository facts. On stdin you receive two
122	numbered lists: CANDIDATES (new facts just extracted from a session) and
123	EXISTING (facts already stored at the same taxonomy paths). For each candidate,
124	decide how it relates to the existing facts.
125	
126	For every candidate output exactly one line, in candidate-number order:
127	
128	    <candidate#> <decision> <existing#-or-dash> <confidence>
129	
130	- <candidate#>: the candidate's number.
131	- <decision>: one of
132	    new        — not represented by any existing fact.
133	    merge       — the SAME meaning as an existing fact (a restatement); consolidate.
134	    supersede   — CONTRADICTS or replaces an existing fact.
135	- <existing#-or-dash>: for merge/supersede, the EXISTING fact number it refers
136	  to; for new, a dash "-".
137	- <confidence>: 0.00 to 1.00, your confidence in a merge/supersede decision
138	  (use 1.0 for new).
139	
140	Rules:
141	- Candidates are newly extracted, not necessarily newer evidence. Session processing may be newest-first; do not infer chronology from which list contains a fact.
142	- A restatement ("use tabs") and a reversal ("use spaces") look similar but are
143	  NOT the same: the first is merge, the second is supersede. Read the meaning.
144	- When unsure between merge/supersede and new, prefer new with lower confidence
145	  rather than wrongly collapsing distinct facts.
146	- Output only these lines. No prose, no headers, no blank lines.
147	
148	Example:
149	1 new - 1.0
150	2 merge 3 0.88
151	3 supersede 1 0.93`
152	}
153	
154	// reconcileInput renders the candidate and existing fact lists for stdin. Both
155	// are numbered 1-based; the agent refers to them by number, and the parser maps
156	// those numbers back to records (existing numbers resolve to fact ids).
157	func reconcileInput(candidates, existing []factRecord) []byte {
158		var b strings.Builder
159		b.WriteString("CANDIDATES\n")
160		for i, c := range candidates {
161			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(c.Paths, ","), c.Text)
162		}
163		b.WriteString("\nEXISTING\n")
164		for i, e := range existing {
165			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(e.Paths, ","), e.Text)
166		}
167		return []byte(b.String())
168	}
169	
170	// parseReconcileActions turns the agent's decision lines into factActions. Each
171	// candidate gets exactly one action: a line that is missing, malformed, or
172	// references an out-of-range existing fact degrades that candidate to `new`
173	// (with a warning) so a parser hiccup never drops a fact or misapplies a
174	// merge/supersede.
175	func parseReconcileActions(output string, candidates, existing []factRecord) ([]factAction, []string) {
176		decided := make(map[int]factAction, len(candidates))
177		var warnings []string
178	
179		for _, raw := range strings.Split(output, "\n") {
180			line := strings.TrimSpace(raw)
181			if line == "" {
182				continue
183			}
184			fields := strings.Fields(line)
185			// Need at least "<candidate#> <decision>". The canonical form is
186			// "<candidate#> <decision> <existing#-or-dash> <confidence>", but lighter
187			// models (gpt-5.3-codex-spark) drop the "-" placeholder for new
188			// ("3 new 1.0") or omit a trailing confidence; handle those per kind below
189			// instead of rejecting the whole line.
190			if len(fields) < 2 {
191				warnings = append(warnings, "reconcile: malformed line: "+truncateString(line, 80))
192				continue
193			}
194			ci, err := strconv.Atoi(fields[0])
195			if err != nil || ci < 1 || ci > len(candidates) {
196				warnings = append(warnings, "reconcile: bad candidate number: "+truncateString(line, 80))
197				continue
198			}
199			candidate := candidates[ci-1]
200			kind := strings.ToLower(fields[1])
201			switch kind {
202			case factActionNew:
203				// Tolerate a missing "-" placeholder. Confidence is the last field when
204				// it is numeric; otherwise default to 1.0 (the prompt's value for new).
205				confidence := 1.0
206				if len(fields) >= 3 {
207					if last := fields[len(fields)-1]; isNumericToken(last) {
208						confidence = parseConfidence(last)
209					}
210				}
211				decided[ci] = factAction{Kind: factActionNew, Confidence: confidence, Candidate: candidate}
212			case factActionMerge, factActionSupersede:
213				if len(fields) < 3 {
214					warnings = append(warnings, fmt.Sprintf("reconcile: %s missing existing number, treating candidate %d as new", kind, ci))
215					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
216					continue
217				}
218				ei, eerr := strconv.Atoi(fields[2])
219				if eerr != nil || ei < 1 || ei > len(existing) {
220					warnings = append(warnings, fmt.Sprintf("reconcile: %s with bad existing number, treating candidate %d as new", kind, ci))
221					decided[ci] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate}
222					continue
223				}
224				// A missing confidence stays 0 so the action is queued for review
225				// rather than auto-applied.
226				confidence := 0.0
227				if len(fields) >= 4 {
228					confidence = parseConfidence(fields[3])
229				}
230				decided[ci] = factAction{Kind: kind, TargetID: existing[ei-1].ID, Confidence: confidence, Candidate: candidate}
231			default:
232				warnings = append(warnings, "reconcile: unknown decision: "+truncateString(line, 80))
233			}
234		}
235	
236		actions := make([]factAction, 0, len(candidates))
237		for i, candidate := range candidates {
238			if action, ok := decided[i+1]; ok {
239				actions = append(actions, action)
240				continue
241			}
242			warnings = append(warnings, fmt.Sprintf("reconcile: no decision for candidate %d, treating as new", i+1))
243			actions = append(actions, factAction{Kind: factActionNew, Confidence: 1.0, Candidate: candidate})
244		}
245		return actions, warnings
246	}
247	
248	// isNumericToken reports whether a token parses as a finite float, used to tell
249	// a trailing confidence value apart from a "-" placeholder or missing field.
250	// NaN/±Inf are rejected: ParseFloat accepts them, but a NaN confidence would
251	// silently bypass the low-confidence gate downstream (every comparison with NaN
252	// is false), so they must not be treated as a numeric confidence.
253	func isNumericToken(token string) bool {
254		value, err := strconv.ParseFloat(token, 64)
255		return err == nil && !math.IsNaN(value) && !math.IsInf(value, 0)
256	}
257	
258	// parseConfidence reads a confidence token, clamped to [0,1]; unparseable
259	// values (including NaN/±Inf, which would otherwise slip past the [0,1] clamp
260	// and the auto-apply threshold) default to 0 so an unreadable confidence is
261	// treated as low and queued for review rather than auto-applied.
262	func parseConfidence(token string) float64 {
263		value, err := strconv.ParseFloat(token, 64)
264		if err != nil || math.IsNaN(value) || math.IsInf(value, 0) {
265			return 0
266		}
267		if value < 0 {
268			return 0
269		}
270		if value > 1 {
271			return 1
272		}
273		return value
274	}
275	
276	// activeFactsAtPaths returns the active facts whose paths intersect the given
277	// path set, most-recently-updated first, capped at maxReconcileExisting. The
278	// boolean reports whether the cap dropped any facts.
279	func activeFactsAtPaths(records []factRecord, paths []string) ([]factRecord, bool) {
280		want := make(map[string]struct{}, len(paths))
281		for _, p := range paths {
282			want[p] = struct{}{}
283		}
284		var matched []factRecord
285		for _, record := range records {
286			if record.Status != factStatusActive {
287				continue
288			}
289			for _, p := range record.Paths {
290				if _, ok := want[p]; ok {
291					matched = append(matched, record)
292					break
293				}
294			}
295		}
296		sort.SliceStable(matched, func(i, j int) bool {
297			if !matched[i].UpdatedAt.Equal(matched[j].UpdatedAt) {
298				return matched[i].UpdatedAt.After(matched[j].UpdatedAt)
299			}
300			return matched[i].ID < matched[j].ID
301		})
302		if len(matched) > maxReconcileExisting {
303			return matched[:maxReconcileExisting], true
304		}
305		return matched, false
306	}
307	
308	// candidatePathSet returns the sorted union of paths across the candidates.
309	func candidatePathSet(candidates []factRecord) []string {
310		seen := map[string]struct{}{}
311		for _, c := range candidates {
312			for _, p := range c.Paths {
313				seen[p] = struct{}{}
314			}
315		}
316		paths := make([]string, 0, len(seen))
317		for p := range seen {
318			paths = append(paths, p)
319		}
320		sort.Strings(paths)
321		return paths
322	}
323	
324	// reconcileChunkCandidates resolves a chunk's candidates against the current
325	// active set: when no existing facts share the candidates' paths, every
326	// candidate is trivially `new` (no agent call); otherwise the agent decides.
327	// An agent error falls back to treating all candidates as `new` so facts are
328	// never lost. It returns the actions to apply plus any warnings.
329	func reconcileChunkCandidates(ctx context.Context, run distillAgentRunner, agentArgs []string, candidates, active []factRecord, repoDir string, timeout time.Duration) ([]factAction, []string) {
330		existing, capped := activeFactsAtPaths(active, candidatePathSet(candidates))
331		if len(existing) == 0 {
332			actions := make([]factAction, len(candidates))
333			for i, c := range candidates {
334				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
335			}
336			return actions, nil
337		}
338		var warnings []string
339		if capped {
340			warnings = append(warnings, fmt.Sprintf("reconcile: more than %d existing facts at these paths; comparing against the %d most recent", maxReconcileExisting, maxReconcileExisting))
341		}
342		out, err := run(ctx, repoDir, agentArgs, reconcileInput(candidates, existing), timeout)
343		if err != nil {
344			warnings = append(warnings, fmt.Sprintf("reconcile agent failed, treating %d candidates as new: %v", len(candidates), err))
345			actions := make([]factAction, len(candidates))
346			for i, c := range candidates {
347				actions[i] = factAction{Kind: factActionNew, Confidence: 1.0, Candidate: c}
348			}
349			return actions, warnings
350		}
351		actions, parseWarnings := parseReconcileActions(out, candidates, existing)
352		return actions, append(warnings, parseWarnings...)
353	}
