		threshold = 2 // above every valid agent confidence
		warnings = append(warnings, "newest-first supersession requires review; both facts retained (run facts review)")
	}
	if action.Kind == factActionMerge || action.Kind == factActionSupersede {
		// The post-ruling guard: a merge/supersede whose two texts share
		// almost no vocabulary is a hallucinated pairing, whatever
		// confidence the agent stamped on it — on the calibration corpus
		// every such ruling was wrong and every genuine one scored >= 0.24.
		// Destruction is irreversible, so these queue for review instead.
		if ti := indexOfFact(active, action.TargetID); ti >= 0 &&
